"/**
 * Models.gs
 * Definisi kelas data model untuk sistem simulasi perhitungan promosi dan refund.
 */

class Product {
  constructor(plu, name, price, fracKrt, priceKrt, benefitRp, benefitPct) {
    this.plu = String(plu).trim();
    this.name = name || '';
    this.price = Number(price) || 0;
    this.fracKrt = Number(fracKrt) || 0;
    this.priceKrt = Number(priceKrt) || 0;
    this.benefitRp = Number(benefitRp) || 0;
    this.benefitPct = Number(benefitPct) || 0;
  }
}

class PromoRule {
  constructor(data) {
    this.type = (data.type || '').trim();
    this.code = (data.code || '').trim();
    this.qtyMin = data.qtyMin !== undefined && data.qtyMin !== '' ? Number(data.qtyMin) : null;
    this.rpMin = data.rpMin !== undefined && data.rpMin !== '' ? Number(data.rpMin) : null;
    this.pctBenefit = data.pctBenefit !== undefined && data.pctBenefit !== '' ? Number(data.pctBenefit) : null;
    this.rpBenefit = data.rpBenefit !== undefined && data.rpBenefit !== '' ? Number(data.rpBenefit) : null;
    this.ptBenefit = data.ptBenefit !== undefined && data.ptBenefit !== '' ? Number(data.ptBenefit) : null;
    this.targetItem = (data.targetItem || '').toString().trim();
    this.pluSyarat = (data.pluSyarat || '').toString().trim();
    this.campur = (data.campur || 'N').toString().trim().toUpperCase();
    this.kelipatan = (data.kelipatan || 'Y').toString().trim().toUpperCase();
    this.qtyMax = data.qtyMax !== undefined && data.qtyMax !== '' ? Number(data.qtyMax) : null;
    this.rpMax = data.rpMax !== undefined && data.rpMax !== '' ? Number(data.rpMax) : null;
    this.sourceRow = data.sourceRow || 0;
    this.resultRow = 0; // Baris pada tabel Tipe Promo di Result tab
  }

  getPluSyaratList() {
    if (!this.pluSyarat || this.pluSyarat.toLowerCase() === 'all plu') return [];
    return this.pluSyarat.split(/[\n,\/]+/).map(p => p.trim()).filter(Boolean);
  }

  isAllPlu() {
    return this.pluSyarat.toLowerCase().includes('all plu');
  }
}

