11: function parseNumber(val) {
12:   if (val === null || val === undefined) return null;
13:   if (typeof val === 'number') {
14:     return isNaN(val) ? null : val;
15:   }
16:   const s = String(val).trim();
17:   if (s === '' || s === '-' || s === '–' || s === '—' || s.toLowerCase() === 'null') {
18:     return null;
19:   }
20:   if (s.endsWith('%')) {
21:     const num = parseFloat(s.slice(0, -1).replace(/,/g, '.'));
22:     return isNaN(num) ? null : num / 100;
23:   }
24:   // Bersihkan format Rp dan pemisah ribuan
25:   const cleanStr = s.replace(/[^0-9.,-]/g, '').replace(/,/g, '');
26:   const num = Number(cleanStr);
27:   return isNaN(num) ? null : num;
28: }
